);","        $this-\u003eredirect('/admin/restaurants/' . $restaurantId . '/edit');","    }","","    public function editRestaurant(string $id): void","    {","        $restaurantId = $this-\u003erestaurantId($id);","","        if ($restaurantId === null) {","            $this-\u003eresponse-\u003ehtml('\u003ch1\u003eRestaurant not found\u003c/h1\u003e', 404);","            return;","        }","","        $restaurant = $this-\u003erestaurantRepository-\u003egetById($restaurantId);","","        if ($restaurant === null) {","            $this-\u003eresponse-\u003ehtml('\u003ch1\u003eRestaurant not found\u003c/h1\u003e', 404);","            return;","        }","","        $this-\u003erenderAdmin('admin/restaurant-form', [","            'title' =\u003e 'Edit restaurant - Taste of Macau',","            'activePage' =\u003e 'admin-restaurants',","            'restaurant' =\u003e $restaurant,","            'restaurantFoods' =\u003e $this-\u003efoodRepository-\u003egetByRestaurant($restaurantId),","            'formAction' =\u003e '/admin/restaurants/' . $restaurantId,","            'mode' =\u003e 'edit',","        ]);","    }","","    public function updateRestaurant(string $id): void","    {","        $restaurantId = $this-\u003erestaurantId($id);","","        if ($restaurantId === null) {","            $this-\u003eresponse-\u003ehtml('\u003ch1\u003eRestaurant not found\u003c/h1\u003e', 404);","            return;","        }","","        if (!$this-\u003evalidateCsrf('/admin/restaurants/' . $restaurantId . '/edit')) {","            return;","        }","","        $data = $this-\u003erestaurantData();","        $errors = $this-\u003evalidateRestaurantData($data);","","        if ($errors !== []) {","            $this-\u003eflashFormState($errors, $data);","            $this-\u003eredirect('/admin/restaurants/' . $restaurantId . '/edit');","            return;","        }","","        $this-\u003erestaurantRepository-\u003eupdate($restaurantId, $this-\u003enormalizedRestaurantData($data));","        $this-\u003esession-\u003eflash('success', 'Restaurant updated.');","        $this-\u003eredirect('/admin/restaurants/' . $restaurantId . '/edit');","    }","","    public function deleteRestaurant(string $id): void","    {","        $restaurantId = $this-\u003erestaurantId($id);","","        if ($restaurantId === null) {","            $this-\u003eresponse-\u003ehtml('\u003ch1\u003eRestaurant not found\u003c/h1\u003e', 404);","            return;","        }","","        if (!$this-\u003evalidateCsrf('/admin/restaurants')) {","            return;","        }","","        $this-\u003erestaurantRepository-\u003edelete($restaurantId);","        $this-\u003esession-\u003eflash('success', 'Restaurant deleted.');","        $this-\u003eredirect('/admin/restaurants');","    }","","    public function feedback(): void","    {","        $this-\u003erenderAdmin('admin/feedback', [","            'title' =\u003e 'Feedback - Taste of Macau',","            'activePage' =\u003e 'admin-feedback',","            'feedbackReports' =\u003e $this-\u003efeedbackRepository-\u003egetAll(),","            'statusCounts' =\u003e $this-\u003efeedbackRepository-\u003ecountByStatus(),","        ]);","    }","","    public function updateFeedbackStatus(string $id): void","    {","        $feedbackId = filter_var($id, FILTER_VALIDATE_INT, ['options' =\u003e ['min_range' =\u003e 1]]);","","        if ($feedbackId === false) {","            $this-\u003eresponse-\u003ehtml('\u003ch1\u003eFeedback not found\u003c/h1\u003e', 404);","            return;","        }","","        if (!$this-\u003evalidateCsrf('/admin/feedback')) {","            return;","        }","","        $status = (string) $this-\u003erequest-\u003epost('status', 'new');","","        if (!in_array($status, ['new', 'reviewing', 'resolved'], true)) {","            $status = 'new';","        }","","        $this-\u003efeedbackRepository-\u003eupdateStatus((int) $feedbackId, $status);","        $this-\u003esession-\u003eflash('success', 'Feedback status updated.');","        $this-\u003eredirect('/admin/feedback');","    }","","    private function renderAdmin(string $template, array $data = []): void","    {","        $locale = $this-\u003eresolveLocale();","","        $this-\u003eview($template, array_merge([","            'app' =\u003e $this-\u003eapp,","            'user' =\u003e $this-\u003ecurrentUser,","            'locale' =\u003e $locale,","            'csrfToken' =\u003e $this-\u003ecsrf-\u003egetToken(),","            'bodyClass' =\u003e 'page-dashboard',","        ], $data));","    }","","    private function renderFoodForm(array $food, string $mode, string $formAction, ?array $restaurantContext = null): void","    {","        $foodId = (int) ($food['id'] ?? 0);","","        $this-\u003erenderAdmin('admin/food-form', [","            'title' =\u003e ($mode === 'edit' ? 'Edit food' : 'Add food') . ' - Taste of Macau',","            'activePage' =\u003e $restaurantContext !== null ? 'admin-restaurants' : 'admin-foods',","            'food' =\u003e $food,","            'categories' =\u003e $this-\u003efoodRepository-\u003egetCategories(),","            'restaurants' =\u003e $this-\u003erestaurantRepository-\u003egetAll(),","            'restaurantLinks' =\u003e $foodId \u003e 0 ? $this-\u003efoodRepository-\u003egetRestaurantLinks($foodId) : [],","            'restaurantContext' =\u003e $restaurantContext,","            'formAction' =\u003e $formAction,","            'mode' =\u003e $mode,","        ]);","    }","","    private function restaurantData(): array","    {","        $fields = [","            'name_en',","            'name_zh',","            'name_pt',","            'description_en',","            'description_zh',","            'description_pt',","            'address_en',","            'address_zh',","            'address_pt',","            'phone',","            'opening_hours',","            'price_range',","            'area_en',","            'area_zh',","            'area_pt',","            'image_url',","        ];","        $data = [];","","        foreach ($fields as $field) {","            $data[$field] = trim((string) $this-\u003erequest-\u003epost($field, ''));","        }","","        $data['latitude'] = trim((string) $this-\u003erequest-\u003epost('latitude', ''));","        $data['longitude'] = trim((string) $this-\u003erequest-\u003epost('longitude', ''));","","        return $data;","    }","","    private function normalizedRestaurantData(array $data): array","    {","        $data['latitude'] = (float) ($data['latitude'] ?? 0);","        $data['longitude'] = (float) ($data['longitude'] ?? 0);","","        return $data;","    }","","    private function foodData(): array","    {","        $fields = [","            'name_en',","            'name_zh',","            'name_pt',","            'description_en',","            'description_zh',","            'description_pt',","            'image_url',","            'area_en',","            'area_zh',","            'area_pt',","            'price_range',","        ];","        $data = [];","","        foreach ($fields as $field) {","            $data[$field] = trim((string) $this-\u003erequest-\u003epost($field, ''));","        }","","        $data['category_id'] = trim((string) $this-\u003erequest-\u003epost('category_id', ''));","        $data['latitude'] = trim((string) $this-\u003erequest-\u003epost('latitude', ''));","        $data['longitude'] = trim((string) $this-\u003erequest-\u003epost('longitude', ''));","        $data['rating'] = trim((string) $this-\u003erequest-\u003epost('rating', '0'));","","        return $data;","    }","","    private function normalizedFoodData(array $data): array","    {","        $data['category_id'] = (int) ($data['category_id'] ?? 0);","        $data['latitude'] = (float) ($data['latitude'] ?? 0);","        $data['longitude'] = (float) ($data['longitude'] ?? 0);","        $data['rating'] = (float) ($data['rating'] ?? 0);","","        return $data;","    }","","    private function validateFoodData(array $data): array","    {","        $errors = [];","","        foreach (['name_zh', 'name_en', 'name_pt'] as $field) {","            if (trim((string) ($data[$field] ?? '')) === '') {","                $errors[$field][] = 'Name is required.';","            }","        }","","        $categoryId = filter_var($data['category_id'] ?? null, FILTER_VALIDATE_INT, ['options' =\u003e ['min_range' =\u003e 1]]);","","        if ($categoryId === false) {","            $errors['category_id'][] = 'Category is required.';","        } else {","            $categoryExists = false;","","            foreach ($this-\u003efoodRepository-\u003egetCategories() as $category) {","                if ((int) ($category['id'] ?? 0) === (int) $categoryId) {","                    $categoryExists = true;","                    break;","                }","            }","","            if (!$categoryExists) {","                $errors['category_id'][] = 'Category is invalid.';","            }","        }","","        foreach (['latitude', 'longitude'] as $field) {","            if (!is_numeric($data[$field] ?? null)) {","                $errors[$field][] = 'Coordinate is required.';","            }","        }","","        if (!is_numeric($data['rating'] ?? null)) {","            $errors['rating'][] = 'Rating must be a number.';","        }","","        if (trim((string) ($data['image_url'] ?? '')) === '') {","            $errors['image_url'][] = 'Image URL is required.';","        }","","        return $errors;","    }","","    private function foodRestaurantLinks(): array","    {","        $restaurantIds = $this-\u003erequest-\u003epost('restaurant_ids', []);","        $signatureIds = $this-\u003erequest-\u003epost('signature_restaurant_ids', []);","","        if (!is_array($restaurantIds)) {","            $restaurantIds = [];","        }","","        if (!is_array($signatureIds)) {","            $signatureIds = [];","        }","","        $signatureLookup = array_fill_keys(array_map('intval', $signatureIds), true);","        $links = [];","","        foreach (array_unique(array_map('intval', $restaurantIds)) as $restaurantId) {","            if ($restaurantId \u003c= 0) {","                continue;","            }","","            $links[] = [","                'restaurant_id' =\u003e $restaurantId,","                'is_signature' =\u003e isset($signatureLookup[$restaurantId]),","            ];","        }","","        return $links;","    }","","    private function syncFoodLinksForContext(int $foodId, ?int $restaurantId): void","    {","        if ($restaurantId !== null) {","            $this-\u003efoodRepository-\u003eupsertRestaurantLink(","                $foodId,","                $restaurantId,","                (bool) $this-\u003erequest-\u003epost('is_signature_for_restaurant', false)","            );","            return;","        }","","        $this-\u003efoodRepository-\u003esyncRestaurantLinks($foodId, $this-\u003efoodRestaurantLinks());","    }","","    private function restaurantContextId(): ?int","    {","        $restaurantId = $this-\u003erequest-\u003epost('restaurant_context_id', null);","","        if ($restaurantId === null || $restaurantId === '') {","            return null;","        }","","        $id = filter_var($restaurantId, FILTER_VALIDATE_INT, ['options' =\u003e ['min_range' =\u003e 1]]);","","        return $id === false ? null : (int) $id;","    }","","    private function restaurantForAdmin(string $id): ?array","    {","        $restaurantId = $this-\u003erestaurantId($id);","","        if ($restaurantId === null) {","            $this-\u003eresponse-\u003ehtml('\u003ch1\u003eRestaurant not found\u003c/h1\u003e', 404);","            return null;","        }","","        $restaurant = $this-\u003erestaurantRepository-\u003egetById($restaurantId);","","        if ($restaurant === null) {","            $this-\u003eresponse-\u00